column.value:
{ 
                "dodgeBonus": 4,
                "target": ["GIANT"],
                "special" : "+4 dodge bonus to Armor Class against monsters of the giant type. Any time a creature loses its Dexterity bonus (if any) to Armor Class, such as when it’s caught flat-footed, it loses its dodge bonus, too."
                }

{ 
                "vsBullRush": 4,
                "special" : "Stability: A dwarf gains a +4 bonus on ability checks made to resist being bull rushed or tripped when standing on the ground (but not when climbing, flying, riding, or otherwise not standing firmly on the ground)"
                }
